func roleChatClass(role string) string {
	switch role {
	case "planner":
		return "chat-start"
	default:
		return "chat-end"
	}
}

func roleLabel(role string) string {
	switch role {
	case "planner":
		return "Planner"
	case "system":
		return "System"
	default:
		return "Creator"
	}
}

func proposalStatusClass(status string) string {
	switch status {
	case "applied":
		return "badge-success"
	case "rejected":
		return "badge-error"
	case "partially_applied":
		return "badge-warning"
	default:
		return "badge-info"
	}
}

func briefField(b *BriefView, key string) string {
	if b == nil {
		return ""
	}
	switch key {
	case "premise":
		return b.Premise
	case "theme":
		return b.Theme
	case "audience":
		return b.Audience
	case "desired_reaction":
		return b.DesiredReaction
	case "pace":
		return b.Pace
	case "excitement":
		return b.Excitement
	case "music_intent":
		return b.MusicIntent
	case "sound_intent":
		return b.SoundIntent
	case "visual_style":
		return b.VisualStyle
	case "camera_language":
		return b.CameraLanguage
	case "production_notes":
		return b.ProductionNotes
	}
	return ""
}

